import pyAether as ae
from typing import List

def get_all_library_names() -> List[str]:
    try:
        libraries = ae.dbListLibraries()
        if isinstance(libraries, list):
            return libraries
        else:
            return [str(lib) for lib in libraries]
    except Exception:
        return []
